        <div className="divide-y divide-zinc-50 px-4">
          {mutations.length === 0 && (
            <p className="py-6 text-center text-xs text-zinc-300">Tidak ada mutasi di rentang ini.</p>
          )}
          {mutations.map((m, i) => (
            <div key={i} className="flex items-center justify-between gap-2 py-2 text-xs">
