(async function(){
  const raw = document.cookie.split('; ').find(c => c.startsWith('sb-mevqavjnjclhegepkiao-auth-token='));
  if (!raw) return 'cookie not found';
  let value = decodeURIComponent(raw.split('=').slice(1).join('='));
  if (value.startsWith('base64-')) {
    value = atob(value.slice('base64-'.length));
  }
  const parsed = JSON.parse(value);
  const token = parsed.access_token;
