const fs = require("fs");

const envText = fs.readFileSync("G:/PROJECT1/KasirKu/.env.local", "utf8");
const env = {};
for (const line of envText.split("\n")) {
  const m = line.match(/^([A-Z_]+)=(.*)$/);
  if (m) env[m[1]] = m[2].trim();
}

const SUPABASE_URL = env.NEXT_PUBLIC_SUPABASE_URL;
const SERVICE_KEY = env.SUPABASE_SERVICE_ROLE_KEY;
const businessId = "8c73640a-2d0c-4e3c-8a85-35e4a3ca89b8";

const headers = {
  apikey: SERVICE_KEY,
  Authorization: `Bearer ${SERVICE_KEY}`,
  "Content-Type": "application/json",
  Prefer: "return=representation",
};

async function main() {
  const step = process.argv[2];

  if (step === "set-active-lapsed") {
    // active monthly plan whose period_end already passed 1 day ago
    const periodEnd = new Date(Date.now() - 1 * 24 * 60 * 60 * 1000).toISOString();
    const res = await fetch(
      `${SUPABASE_URL}/rest/v1/subscriptions?business_id=eq.${businessId}`,
      { method: "PATCH", headers, body: JSON.stringify({ status: "active", plan_code: "monthly", period_end: periodEnd }) },
    );
    console.log(await res.text());
  } else if (step === "set-past-due-lapsed") {
    // past_due whose period_end was 4 days ago (past the 3-day grace period)
    const periodEnd = new Date(Date.now() - 4 * 24 * 60 * 60 * 1000).toISOString();
    const res = await fetch(
      `${SUPABASE_URL}/rest/v1/subscriptions?business_id=eq.${businessId}`,
      { method: "PATCH", headers, body: JSON.stringify({ status: "past_due", plan_code: "monthly", period_end: periodEnd }) },
    );
    console.log(await res.text());
  } else if (step === "read") {
    const res = await fetch(
      `${SUPABASE_URL}/rest/v1/subscriptions?business_id=eq.${businessId}&select=status,plan_code,period_end`,
      { headers },
    );
    console.log(await res.text());
  }
}

main();

