}

const SUPABASE_URL = env.NEXT_PUBLIC_SUPABASE_URL;
const SERVICE_KEY = env.SUPABASE_SERVICE_ROLE_KEY;
const testUserId = "59879268-8070-48ae-b396-5194fbd2a4f8";

const headers = {
  apikey: SERVICE_KEY,
  Authorization: `Bearer ${SERVICE_KEY}`,
  "Content-Type": "application/json",
  Prefer: "return=representation",
};

async function main() {
  const step = process.argv[2];

  if (step === "grant") {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/admins`, {
      method: "POST",
      headers,
      body: JSON.stringify({ user_id: testUserId }),
    });
    console.log(res.status, await res.text());
  } else if (step === "revoke") {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/admins?user_id=eq.${testUserId}`, {
      method: "DELETE",
      headers,
    });
    console.log(res.status, await res.text());
  } else if (step === "check") {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/admins?user_id=eq.${testUserId}`, {
      headers,
    });
    console.log(res.status, await res.text());
  }
}

main();

